/* test_dequant — validates the scalar dequant kernels against golden data
 * generated by gguf-py (tools/py/gen_dequant_golden.py). Golden file format:
 * repeated records of { u32 ggml_type, u32 n_blocks, raw bytes, f32 values }.
 * Usage: test_dequant [path/to/dequant_golden.bin] */
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "fatcat/dequant.h"
#include "fatcat/gguf.h"

static int failures;
#define CHECK(cond)                                                          \
    do {                                                                     \
        if (!(cond)) {                                                       \
            fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
            failures++;                                                      \
        }                                                                    \
    } while (0)

static uint32_t rd_u32(FILE *f)
{
    uint32_t v;
    if (fread(&v, 4, 1, f) != 1) { fprintf(stderr, "truncated golden file\n"); exit(2); }
    return v;
}

int main(int argc, char **argv)
{
    const char *path = argc > 1 ? argv[1] : "tests/data/dequant_golden.bin";
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); return 2; }

    int n_records = 0;
    while (1) {
        uint32_t type, nblocks;
        if (fread(&type, 4, 1, f) != 1) break; /* EOF */
        nblocks = rd_u32(f);
        uint32_t block, bytes;
        CHECK(fatcat_ggml_type_size(type, &block, &bytes));
        size_t raw_len = (size_t)nblocks * bytes;
        uint8_t *raw = malloc(raw_len);
        float *expect = malloc((size_t)nblocks * block * 4);
        CHECK(fread(raw, 1, raw_len, f) == raw_len);
        CHECK(fread(expect, 4, (size_t)nblocks * block, f) == (size_t)nblocks * block);

        float *got = malloc((size_t)nblocks * block * 4);
        CHECK(fatcat_dequant(type, raw, got, (uint64_t)nblocks * block));

        /* compare: exact for f32/f16/q8_0/q6_k (all f32-scaled ints),
         * tiny tolerance for iq2 (f32 multiply order) */
        double max_abs = 0, max_rel = 0;
        for (uint64_t i = 0; i < (uint64_t)nblocks * block; i++) {
            double a = got[i], b = expect[i];
            double ad = fabs(a - b);
            if (ad > max_abs) max_abs = ad;
            if (b != 0) {
                double rel = ad / fabs(b);
                if (rel > max_rel) max_rel = rel;
            }
        }
        printf("record %d: type=%u blocks=%u max_abs=%.3g max_rel=%.3g\n",
               n_records, type, nblocks, max_abs, max_rel);
        CHECK(max_abs < 1e-6 || max_rel < 1e-6);

        free(raw); free(expect); free(got);
        n_records++;
    }
    fclose(f);
    CHECK(n_records == 4);

    if (failures) { printf("test_dequant: %d FAILURE(S)\n", failures); return 1; }
    printf("test_dequant: PASS (%d records)\n", n_records);
    return 0;
}
